    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    const long long MOD = 1000000007LL;
    int limit = max(n, m);
    vector<long long> f(max(3, limit + 1), 0);

    f[1] = 1;
    f[2] = 2;
    for (int i = 3; i <= limit; ++i) {
        f[i] = (f[i - 1] + f[i - 2]) % MOD;
